CompositionLocalProvider(LocalConfiguration provides locale) {
    Column(Modifier.verticalScroll(rememberScrollState())) {
        MonarchBusinessHoursEditor(
            value = hours,
            onValueChange = { hours = it },
            showDefault = true,
            requireName = true,
            requireOpen = true,
            showErrors = saveTried,
            pinnedTimeZones = listOf({{pinnedTimeZones.0}}, {{pinnedTimeZones.1}}, {{pinnedTimeZones.2}}),
            firstDayOfWeek = {{firstWeekday}},
            is24Hour = {{twentyFourHour}},
        )
        MonarchButton(
            text = {{save}},
            onClick = {
                saveTried = true
                if (hours.validate(requireName = true, requireOpen = true).valid) { /* Save hours. */ }
            },
            variant = MonarchButtonVariant.Primary,
        )
    }
}

examples.setupTemplate:
var hours by remember {
    mutableStateOf(
        MonarchBusinessHoursValue(
            timeZone = {{timeZone}},
            hours = listOf({{weekdays.0}}, {{weekdays.1}}, {{weekdays.2}}, {{weekdays.3}}, {{weekdays.4}}).map {
                MonarchWeeklyHoursInterval(it, {{start}}, {{end}})
            },
            exceptions = listOf(
                MonarchBusinessHoursException({{exceptions.0.date|millis}}, {{exceptions.0.name}}),
                MonarchBusinessHoursException(
                    {{exceptions.1.date|millis}},
                    {{exceptions.1.name}},
                    listOf(MonarchBusinessHoursInterval({{exceptions.1.start}}, {{exceptions.1.end}})),
                ),
            ),
            name = {{name}},
        ),
    )
}
var saveTried by rememberSaveable { mutableStateOf(false) }
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

