            hours = listOf(1, 2, 3, 4, 5).map {
                MonarchWeeklyHoursInterval(it, 540, 1050)
            },
            exceptions = listOf(
                MonarchBusinessHoursException(1_798_156_800_000L, "Christmas Day"),
                MonarchBusinessHoursException(
                    1_798_675_200_000L,
                    "New Year’s Eve",
                    listOf(MonarchBusinessHoursInterval(540, 780)),
                ),
            ),
            name = "Support hours",
        ),
    )
}
var saveTried by rememberSaveable { mutableStateOf(false) }
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}

